Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('f46087a586d9cf2631eb9e90afb2f167230c48cb57dfa467e11637603e529fd4',), event=Revised(decision='protondrive', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title="Proton Drive is the secretary's by permission: two reads, two writes, an allow-list and redacted ID numbers", body="*Proton Drive is the secretary's by permission* (2026-09-25): the CLI is reached only through a closed enum of two reads (list, download) and two writes (create-folder, upload) that `ProtonDrive::keep` alone uses, a file outside a `[secretary] drive_allow` folder is read only on a tap, and every SSN/ITIN/TIN/EIN is `redact`ed (`Redacted` is the only type a read answers in) before a transcript or a model sees it; the triage agent gets no Drive.", rationale='Decided 2026-09-25. Restated 2026-11-20: the plan it cited was deleted.', supersedes=()))